import React, { useState, useCallback, useEffect } from "react";

// localStorage管理
const LS_USED = "fe_used_ids";
const LS_SESSIONS = "fe_sessions";
const LS_MISSED = "fe_missed";
const LS_LIFETIME = "fe_lifetime"; // 生涯累計(セッション履歴とは別に、間引かれず増え続ける集計)
const LS_CYCLE = "fe_cycle"; // 今回の周回成績(問題プールを1周する間、リロードしても消えない)
const LS_QVERSION = "fe_qversion"; // 問題内容のバージョン識別子(内容が変わったら周回・復習リストを自動リセットするために使う)

const store = {
  saveIds(ids){ try{ localStorage.setItem(LS_USED, JSON.stringify(ids)); }catch(e){} },
  loadIds(){ try{ const v=localStorage.getItem(LS_USED); return v?JSON.parse(v):[]; }catch(e){ return []; } },
  addSession(session){
    try{
      // 生涯累計を先に確定(この時点ではまだ今回のsessionを含まない状態で
      // 初回マイグレーションのベースラインを作る。二重計上を防ぐため必ず
      // sessionsの更新より前に行う)
      const lt = this.loadLifetime();
      lt.totalAnswered += session.total;
      lt.totalCorrect += session.correct;
      Object.entries(session.cats||{}).forEach(([c,v])=>{
        if(!lt.byCat[c]) lt.byCat[c] = {ok:0,total:0};
        lt.byCat[c].ok += v.ok;
        lt.byCat[c].total += v.total;
      });
      this.saveLifetime(lt);

      const sessions = this.loadSessions();
      sessions.push(session);
      // 直近セッション一覧の表示用に最新100件だけ保持(この間引きは表示用のみで、
      // 累計成績はfe_lifetimeに別途加算保存するため間引きの影響を受けない)
      if(sessions.length > 100) sessions.splice(0, sessions.length - 100);
      localStorage.setItem(LS_SESSIONS, JSON.stringify(sessions));
    }catch(e){}
  },
  loadSessions(){ try{ const v=localStorage.getItem(LS_SESSIONS); return v?JSON.parse(v):[]; }catch(e){ return []; } },
  saveLifetime(lt){ try{ localStorage.setItem(LS_LIFETIME, JSON.stringify(lt)); }catch(e){} },
  loadLifetime(){
    try{
      const v = localStorage.getItem(LS_LIFETIME);
      if(v) return JSON.parse(v);
    }catch(e){}
    // 初回: fe_lifetimeが存在しない場合、既存のfe_sessions(直近最大100件、
    // =この呼び出し時点でまだ今回のsessionは含まれていない)の合計値を初期値として
    // 引き継ぐ。これより前に間引かれてしまった分は復元不可能だが、
    // 以後は間引かれずに正しく積み上がっていく。
    const sessions = this.loadSessions();
    const lt = { totalAnswered:0, totalCorrect:0, byCat:{} };
    sessions.forEach(sess=>{
      lt.totalAnswered += sess.total;
      lt.totalCorrect += sess.correct;
      Object.entries(sess.cats||{}).forEach(([c,v])=>{
        if(!lt.byCat[c]) lt.byCat[c] = {ok:0,total:0};
        lt.byCat[c].ok += v.ok;
        lt.byCat[c].total += v.total;
      });
    });
    return lt;
  },
  saveMissed(list){ try{ localStorage.setItem(LS_MISSED, JSON.stringify(list)); }catch(e){} },
  loadMissed(){ try{ const v=localStorage.getItem(LS_MISSED); return v?JSON.parse(v):[]; }catch(e){ return []; } },
  // 今回の周回成績: 問題プールを1周する(usedIdsがリセットされる)まで保持し、
  // ページのリロードやタブの再読込では消えないようにする
  saveCycle(data){ try{ localStorage.setItem(LS_CYCLE, JSON.stringify(data)); }catch(e){} },
  loadCycle(){ try{ const v=localStorage.getItem(LS_CYCLE); return v?JSON.parse(v):{history:[],catStats:{}}; }catch(e){ return {history:[],catStats:{}}; } },
  clearCycle(){ try{ localStorage.removeItem(LS_CYCLE); }catch(e){} },
};

const CATS = [
  "すべて","基礎理論","コンピュータシステム","ネットワーク","情報セキュリティ",
  "データベース","アルゴリズム・プログラミング","ソフトウェア・HI",
  "システム開発","プロジェクトマネジメント","サービスマネジメント・監査","経営・戦略・法務",
];

const ALL_QUESTIONS = [{"id":1,"cat":"基礎理論","topic":"計算量オーダーの実感的理解","q":"処理するデータ件数が10倍になったとき、実行時間もほぼ10倍になるアルゴリズムの計算量オーダーはどれか。","choices":[{"label":"ア","text":"O(log n)"},{"label":"イ","text":"O(1)"},{"label":"ウ","text":"O(n²)"},{"label":"エ","text":"O(n)"}],"correct":"エ","hint":"計算量がデータ件数nに正比例して増加するオーダーがO(n)である。"},{"id":2,"cat":"基礎理論","topic":"2の補数表現の変換","q":"8ビットの2の補数表現で11111110が表す10進数の値はどれか。","choices":[{"label":"ア","text":"254"},{"label":"イ","text":"-2"},{"label":"ウ","text":"-1"},{"label":"エ","text":"126"}],"correct":"イ","hint":"全ビットを反転し1を加えると00000010(10進2)になるため、元の値は-2である。"},{"id":3,"cat":"基礎理論","topic":"パリティビットによる誤り検出の限界","q":"奇数パリティ方式で送信したデータを受信した際、1の個数が偶数だった場合に判断できることはどれか。","choices":[{"label":"ア","text":"どのビットが誤ったか特定できる"},{"label":"イ","text":"誤りは全く発生していない"},{"label":"ウ","text":"奇数個のビット誤りが発生している"},{"label":"エ","text":"偶数個のビット誤りが発生している"}],"correct":"ウ","hint":"パリティは1ビット誤り(奇数個の誤り)は検出できるが誤り箇所の特定や2ビット誤りの検出はできない。"},{"id":4,"cat":"基礎理論","topic":"順列の計算(応用)","q":"8人の中から3人を選んで一列に並べる場合の数はどれか。","choices":[{"label":"ア","text":"336"},{"label":"イ","text":"56"},{"label":"ウ","text":"24"},{"label":"エ","text":"512"}],"correct":"ア","hint":"8P3=8×7×6=336として求められる。"},{"id":5,"cat":"基礎理論","topic":"ハッシュ探索の理想条件","q":"要素数が非常に多いハッシュ表において、ハッシュ関数の衝突が全く発生しないと仮定した場合の探索の計算量はどれか。","choices":[{"label":"ア","text":"O(log n)"},{"label":"イ","text":"O(n²)"},{"label":"ウ","text":"O(1)"},{"label":"エ","text":"O(n)"}],"correct":"ウ","hint":"衝突がなければキーからハッシュ値を計算し1回のアクセスで要素に到達できる。"},{"id":6,"cat":"基礎理論","topic":"集合演算の応用計算","q":"全体集合Uの要素数が100、集合Aの要素数が40、集合Bの要素数が30、AとBの共通部分の要素数が10のとき、AにもBにも属さない要素数はどれか。","choices":[{"label":"ア","text":"40"},{"label":"イ","text":"60"},{"label":"ウ","text":"30"},{"label":"エ","text":"20"}],"correct":"ア","hint":"|A∪B|=40+30-10=60であり、100-60=40がどちらにも属さない要素数となる。"},{"id":7,"cat":"基礎理論","topic":"論理式の真理値判定","q":"論理式「(A OR B) AND (NOT A)」が真になるのは、AとBがそれぞれどのような値のときか。","choices":[{"label":"ア","text":"A=真、B=真"},{"label":"イ","text":"A=偽、B=真"},{"label":"ウ","text":"A=真、B=偽"},{"label":"エ","text":"A=偽、B=偽"}],"correct":"イ","hint":"NOT Aが真である必要があるためAは偽、かつA OR Bが真である必要があるためBは真でなければならない。"},{"id":8,"cat":"基礎理論","topic":"二分探索木の構築順序","q":"5, 3, 8, 1, 4という順序で二分探索木へ要素を挿入した場合、根(root)になる値はどれか。","choices":[{"label":"ア","text":"3"},{"label":"イ","text":"8"},{"label":"ウ","text":"1"},{"label":"エ","text":"5"}],"correct":"エ","hint":"最初に挿入された要素がその後の挿入によって移動することなく根になる。"},{"id":9,"cat":"基礎理論","topic":"浮動小数点演算の丸め誤差","q":"0.1を10回繰り返し加算した結果と、最初から1.0として扱った値とでは、一般に浮動小数点演算上どちらが正確な1.0に近い値になるか。","choices":[{"label":"ア","text":"10回加算した値の方が正確"},{"label":"イ","text":"最初から1.0として扱った値の方が正確"},{"label":"ウ","text":"どちらも完全に同じ値になる"},{"label":"エ","text":"どちらも1.0より必ず大きくなる"}],"correct":"イ","hint":"0.1は2進浮動小数点で正確に表現できないため、加算を繰り返すほど丸め誤差が蓄積しやすい。"},{"id":10,"cat":"基礎理論","topic":"再帰関数の必須要素","q":"再帰関数を定義する際、無限に呼び出しが続くことを防ぐために必ず必要な要素はどれか。","choices":[{"label":"ア","text":"引数のデフォルト値"},{"label":"イ","text":"ローカル変数の宣言"},{"label":"ウ","text":"基底条件(再帰を終了させる停止条件)"},{"label":"エ","text":"戻り値の型指定"}],"correct":"ウ","hint":"停止条件がないと呼び出しが無限に続きスタックオーバーフローを引き起こす。"},{"id":11,"cat":"コンピュータシステム","topic":"実効アクセス時間の計算(応用)","q":"キャッシュのアクセス時間5ns、主記憶のアクセス時間50ns、キャッシュヒット率80%のときの実効アクセス時間に最も近い値はどれか。","choices":[{"label":"ア","text":"14ns"},{"label":"イ","text":"50ns"},{"label":"ウ","text":"5ns"},{"label":"エ","text":"40ns"}],"correct":"ア","hint":"0.8×5+0.2×50=4+10=14という重み付き平均で概算できる。"},{"id":12,"cat":"コンピュータシステム","topic":"直列システムの稼働率計算(応用)","q":"稼働率0.9の装置Aと稼働率0.8の装置Bを直列に接続したシステム全体の稼働率はどれか。","choices":[{"label":"ア","text":"0.85"},{"label":"イ","text":"0.9"},{"label":"ウ","text":"0.98"},{"label":"エ","text":"0.72"}],"correct":"エ","hint":"直列システムの稼働率は各装置の稼働率の積(0.9×0.8)で求まる。"},{"id":13,"cat":"コンピュータシステム","topic":"RAID構成の選定(応用)","q":"予算に制約があり、冗長性より読み書き速度を優先したいシステムに適したRAID構成はどれか。","choices":[{"label":"ア","text":"RAID1"},{"label":"イ","text":"RAID5"},{"label":"ウ","text":"RAID6"},{"label":"エ","text":"RAID0"}],"correct":"エ","hint":"RAID0はストライピングのみで冗長性を持たない代わりに速度を追求した構成。"},{"id":14,"cat":"コンピュータシステム","topic":"割込み方式の選定(応用)","q":"CPUの処理能力を無駄に消費せず、周辺機器からの通知に迅速に反応したい場合に適した制御方式はどれか。","choices":[{"label":"ア","text":"割込み処理"},{"label":"イ","text":"ポーリング"},{"label":"ウ","text":"パイプライン処理"},{"label":"エ","text":"マルチプログラミング"}],"correct":"ア","hint":"ポーリングは常時監視が必要でCPU負荷が高くなりやすい。"},{"id":15,"cat":"コンピュータシステム","topic":"仮想記憶方式の目的(応用)","q":"主記憶の物理的な容量を超えるサイズのプログラムを実行できるようにする仕組みはどれか。","choices":[{"label":"ア","text":"パイプライン処理"},{"label":"イ","text":"仮想記憶"},{"label":"ウ","text":"キャッシュメモリ"},{"label":"エ","text":"マルチコア"}],"correct":"イ","hint":"補助記憶を組み合わせ、あたかも大容量の主記憶があるかのように見せる仕組み。"},{"id":16,"cat":"コンピュータシステム","topic":"アムダールの法則(応用)","q":"並列化できない処理が全体の20%を占める場合、コア数を無限に増やしても得られる理論上の最大速度向上倍率はどれか。","choices":[{"label":"ア","text":"20倍"},{"label":"イ","text":"10倍"},{"label":"ウ","text":"5倍"},{"label":"エ","text":"無限大"}],"correct":"ウ","hint":"アムダールの法則により最大速度向上は1÷0.2=5倍が上限となる。"},{"id":17,"cat":"コンピュータシステム","topic":"スループットの計算(応用)","q":"1件あたり平均10ミリ秒を要する処理を単純に逐次実行する場合、1秒間に処理できる最大件数はどれか。","choices":[{"label":"ア","text":"1000件"},{"label":"イ","text":"60件"},{"label":"ウ","text":"10件"},{"label":"エ","text":"100件"}],"correct":"エ","hint":"1000ミリ秒÷10ミリ秒=100件として求められる。"},{"id":18,"cat":"コンピュータシステム","topic":"キャッシュ書込み方式の選定(応用)","q":"書込み頻度が非常に高い処理において、主記憶への反映を後回しにしてメモリバスの負荷を減らしたい場合に適したキャッシュ方式はどれか。","choices":[{"label":"ア","text":"ライトスルー方式"},{"label":"イ","text":"ノーライトアロケート方式"},{"label":"ウ","text":"ライトバック方式"},{"label":"エ","text":"ライトアラウンド方式"}],"correct":"ウ","hint":"書込みのたびに主記憶へ即時反映しない分、バス負荷を抑えられる。"},{"id":19,"cat":"コンピュータシステム","topic":"フェイルソフトの適用場面(応用)","q":"障害発生時に、一部の機能を制限してでもシステム全体の稼働を継続させたい場合に採用する設計方針はどれか。","choices":[{"label":"ア","text":"フェイルソフト(縮退運転)"},{"label":"イ","text":"フォールバック"},{"label":"ウ","text":"フェイルセーフ"},{"label":"エ","text":"フェイルオーバー"}],"correct":"ア","hint":"機能を落としてでも稼働を止めないという考え方である。"},{"id":20,"cat":"コンピュータシステム","topic":"アドレス指定方式の選定(応用)","q":"頻繁に参照される固定アドレスへ最速でアクセスしたい場合に適したアドレス指定方式はどれか。","choices":[{"label":"ア","text":"間接アドレス指定方式"},{"label":"イ","text":"直接アドレス指定方式"},{"label":"ウ","text":"相対アドレス指定方式"},{"label":"エ","text":"インデックスアドレス指定方式"}],"correct":"イ","hint":"メモリ参照が1回で済むため、間接アドレス指定より高速にアクセスできる。"},{"id":21,"cat":"ネットワーク","topic":"サブネット分割の設計(応用)","q":"192.168.1.0/24のネットワークを4つの同じ大きさのサブネットに均等分割する場合、各サブネットのプレフィックス長はどれか。","choices":[{"label":"ア","text":"/25"},{"label":"イ","text":"/26"},{"label":"ウ","text":"/28"},{"label":"エ","text":"/27"}],"correct":"イ","hint":"4分割するには2ビット追加すればよく、/24+2=/26となる。"},{"id":22,"cat":"ネットワーク","topic":"HTTPS通信のポート番号(応用)","q":"社内端末からインターネット上のWebサーバへHTTPSでアクセスする際、宛先として使われる標準のポート番号はどれか。","choices":[{"label":"ア","text":"21"},{"label":"イ","text":"80"},{"label":"ウ","text":"443"},{"label":"エ","text":"25"}],"correct":"ウ","hint":"TLSで暗号化されたHTTP通信は標準で443番ポートを使用する。"},{"id":23,"cat":"ネットワーク","topic":"DNS名前解決の役割(応用)","q":"利用者がブラウザにURLを入力した際、対応するWebサーバのIPアドレスを取得するために使われる仕組みはどれか。","choices":[{"label":"ア","text":"DNS(正引き)"},{"label":"イ","text":"DHCP"},{"label":"ウ","text":"ARP"},{"label":"エ","text":"NAT"}],"correct":"ア","hint":"ドメイン名からIPアドレスを調べる、DNSの最も基本的な機能である。"},{"id":24,"cat":"ネットワーク","topic":"トランスポート層プロトコルの選定(応用)","q":"多少のパケットロスは許容してもよいので、遅延の少なさを最優先したい音声通話アプリに適したトランスポート層プロトコルはどれか。","choices":[{"label":"ア","text":"ICMP"},{"label":"イ","text":"TCP"},{"label":"ウ","text":"SCTP"},{"label":"エ","text":"UDP"}],"correct":"エ","hint":"再送制御による遅延を避けたいリアルタイム通信ではUDPが選ばれることが多い。"},{"id":25,"cat":"ネットワーク","topic":"VPN技術の選定(応用)","q":"拠点間を、あたかも専用回線でつながっているかのように暗号化して接続したい場合に用いる技術はどれか。","choices":[{"label":"ア","text":"CDN"},{"label":"イ","text":"VLAN"},{"label":"ウ","text":"VPN(IPsec等)"},{"label":"エ","text":"NAT"}],"correct":"ウ","hint":"公衆回線上に暗号化されたトンネルを構築し、専用線のような通信を実現する。"},{"id":26,"cat":"ネットワーク","topic":"経路制御プロトコルの選定2(応用)","q":"小規模で構成変化の少ない組織内ネットワークにおいて、設定の簡単さを優先したい場合に適した経路制御プロトコルはどれか。","choices":[{"label":"ア","text":"BGP"},{"label":"イ","text":"OSPF"},{"label":"ウ","text":"ARP"},{"label":"エ","text":"RIP"}],"correct":"エ","hint":"距離ベクトル型のRIPは大規模網には向かないが、小規模網ではシンプルに導入できる。"},{"id":27,"cat":"ネットワーク","topic":"NAPTの必要性(応用)","q":"社内の複数の端末が、限られた1つのグローバルIPアドレスを共有してインターネットへアクセスできるようにする技術はどれか。","choices":[{"label":"ア","text":"NAPT(IPマスカレード)"},{"label":"イ","text":"ARP"},{"label":"ウ","text":"DHCP"},{"label":"エ","text":"DNS"}],"correct":"ア","hint":"ポート番号を使って複数端末の通信を1つのグローバルIPで多重化する。"},{"id":28,"cat":"ネットワーク","topic":"伝送時間の計算(応用)","q":"伝送速度100Mbpsの回線で10MBのファイルをダウンロードするのにかかる理論上の最短時間に最も近いものはどれか(1バイト=8ビット、オーバーヘッドは無視する)。","choices":[{"label":"ア","text":"1.25秒"},{"label":"イ","text":"0.8秒"},{"label":"ウ","text":"8秒"},{"label":"エ","text":"80秒"}],"correct":"イ","hint":"10MB=80Mbitであり、100Mbpsの回線では80÷100=0.8秒で転送できる計算になる。"},{"id":29,"cat":"ネットワーク","topic":"ループ防止技術の選定(応用)","q":"冗長化のためにスイッチ2台を2本のケーブルで接続したところブロードキャストストームが発生した。これを防ぐために有効な技術はどれか。","choices":[{"label":"ア","text":"VLAN"},{"label":"イ","text":"リンクアグリゲーション"},{"label":"ウ","text":"スパニングツリープロトコル(STP)"},{"label":"エ","text":"NAT"}],"correct":"ウ","hint":"冗長経路の一部を論理的にブロックしループの発生を防ぐ。"},{"id":30,"cat":"ネットワーク","topic":"TTLエラーの原因推定(応用)","q":"pingコマンドの実行中に「TTL exceeded」というエラーが繰り返し表示される場合、最も疑われる原因はどれか。","choices":[{"label":"ア","text":"宛先ホストの電源が切れている"},{"label":"イ","text":"DNSの設定が誤っている"},{"label":"ウ","text":"ケーブルが断線している"},{"label":"エ","text":"ルーティングループが発生している"}],"correct":"エ","hint":"パケットがルータ間を巡回し続けTTLが0になった時点でこのエラーが発生する。"},{"id":31,"cat":"情報セキュリティ","topic":"認証強化策の選定(応用)","q":"パスワードのみによる認証で不正ログインが多発している場合、追加すべき対策として最も効果的なものはどれか。","choices":[{"label":"ア","text":"ログイン画面のデザイン変更"},{"label":"イ","text":"多要素認証(二要素認証)の導入"},{"label":"ウ","text":"パスワード入力欄の非表示化のみ"},{"label":"エ","text":"パスワードの定期変更ルール強化のみ"}],"correct":"イ","hint":"知識情報に加えて所持情報等を組み合わせることで不正ログインのリスクを大きく下げられる。"},{"id":32,"cat":"情報セキュリティ","topic":"通信の暗号化対策(応用)","q":"Webサイトとの通信内容が盗聴されるリスクを防ぎたい場合に導入すべき技術はどれか。","choices":[{"label":"ア","text":"TLS/SSL(HTTPS化)"},{"label":"イ","text":"IDS"},{"label":"ウ","text":"WAF"},{"label":"エ","text":"ファイアウォール"}],"correct":"ア","hint":"通信経路そのものを暗号化することで盗聴を防止する。"},{"id":33,"cat":"情報セキュリティ","topic":"ランサムウェア感染時の初動対応(応用)","q":"社内PCがランサムウェアに感染したことが判明した。最初に取るべき行動はどれか。","choices":[{"label":"ア","text":"ネットワークから当該端末を切り離す"},{"label":"イ","text":"全社員へ一斉にメールで詳細を周知する"},{"label":"ウ","text":"感染ファイルをそのまま開いて内容を確認する"},{"label":"エ","text":"すぐに端末を再起動する"}],"correct":"ア","hint":"まず被害の拡大を止めることを優先し、原因究明や周知はその後に行う。"},{"id":34,"cat":"情報セキュリティ","topic":"脆弱性対応の優先順位(応用)","q":"使用中のソフトウェアに重大な脆弱性が発見され、修正パッチが公開された。取るべき対応はどれか。","choices":[{"label":"ア","text":"次回の定期メンテナンスまで様子を見る"},{"label":"イ","text":"脆弱性情報の公開を差し止める"},{"label":"ウ","text":"パッチの適用は不要と判断する"},{"label":"エ","text":"速やかにパッチを適用する"}],"correct":"エ","hint":"既知の脆弱性を悪用する攻撃への基本的かつ重要な対策となる。"},{"id":35,"cat":"情報セキュリティ","topic":"パスワード使い回しのリスク(応用)","q":"同じパスワードを複数のサービスで使い回している場合に高まるリスクはどれか。","choices":[{"label":"ア","text":"ログイン速度が低下するリスク"},{"label":"イ","text":"パスワードを覚えやすくなるリスク"},{"label":"ウ","text":"いずれかのサービスから漏えいしたパスワードが他サービスへの不正ログインに悪用されるリスク"},{"label":"エ","text":"アカウントロックが発生しにくくなるリスク"}],"correct":"ウ","hint":"いわゆるパスワードリスト攻撃による被害拡大につながる。"},{"id":36,"cat":"情報セキュリティ","topic":"内部不正対策(応用)","q":"退職予定の従業員による機密情報の持ち出しリスクを低減するために有効な対策はどれか。","choices":[{"label":"ア","text":"監視カメラの増設のみで対応する"},{"label":"イ","text":"退職前にアクセス権限を速やかに見直し・削除する"},{"label":"ウ","text":"退職者にも従来どおりの権限を残しておく"},{"label":"エ","text":"特に対策は不要である"}],"correct":"イ","hint":"職務に必要な権限を必要な期間だけ与える最小権限の原則に基づく対応。"},{"id":37,"cat":"情報セキュリティ","topic":"XSS脆弱性の識別(応用)","q":"利用者が入力した値をそのままHTMLとして出力する掲示板アプリで、悪意あるスクリプトが他の閲覧者のブラウザ上で実行されてしまう脆弱性はどれか。","choices":[{"label":"ア","text":"XSS(クロスサイトスクリプティング)"},{"label":"イ","text":"SQLインジェクション"},{"label":"ウ","text":"ディレクトリトラバーサル"},{"label":"エ","text":"CSRF"}],"correct":"ア","hint":"出力時のエスケープ処理不足が主な原因となる。"},{"id":38,"cat":"情報セキュリティ","topic":"ランサムウェア対策としてのバックアップ運用(応用)","q":"ランサムウェア対策として、バックアップデータを保管する際に特に注意すべき点はどれか。","choices":[{"label":"ア","text":"バックアップの暗号化は行わない"},{"label":"イ","text":"バックアップを本番環境から論理的・物理的に分離して保管する"},{"label":"ウ","text":"バックアップの取得頻度をできるだけ減らす"},{"label":"エ","text":"本番サーバの同一ディスク内に保存する"}],"correct":"イ","hint":"本番環境と同一のネットワーク上にあると、バックアップごと暗号化される被害を受けかねない。"},{"id":39,"cat":"情報セキュリティ","topic":"SSL/TLSサーバ証明書の役割(応用)","q":"Webサイトの運営者が正当な事業者であることを、利用者のブラウザ上で確認できるようにするために必要なものはどれか。","choices":[{"label":"ア","text":"ファイアウォール"},{"label":"イ","text":"IDS"},{"label":"ウ","text":"SSL/TLSサーバ証明書"},{"label":"エ","text":"WAF"}],"correct":"ウ","hint":"認証局が発行した証明書により、通信相手が正当なサーバであることを検証できる。"},{"id":40,"cat":"情報セキュリティ","topic":"ソーシャルエンジニアリング対策(応用)","q":"取引先を装った電話でパスワードを聞き出そうとする行為への最も基本的な対策はどれか。","choices":[{"label":"ア","text":"電話機を新しい機種に交換する"},{"label":"イ","text":"社内の全ての電話を廃止する"},{"label":"ウ","text":"パスワードを定期的に変更するのみで対応する"},{"label":"エ","text":"電話や口頭でパスワード等の機密情報を伝えないという社内ルールを徹底する"}],"correct":"エ","hint":"技術的対策ではなく、人の運用ルールとして徹底することが有効な対策となる。"},{"id":41,"cat":"データベース","topic":"正規化による設計改善(応用)","q":"「注文番号」ごとに「顧客名」「顧客住所」の列が繰り返し格納されており、同じ顧客の注文が増えるたびに顧客情報が重複してしまう設計になっている。この問題を解消するために必要な変更はどれか。","choices":[{"label":"ア","text":"注文テーブルのインデックスを増やす"},{"label":"イ","text":"顧客情報を別テーブルに分離し正規化する"},{"label":"ウ","text":"注文番号の桁数を増やす"},{"label":"エ","text":"顧客名の文字列長を短くする"}],"correct":"イ","hint":"顧客テーブルを分離し注文テーブルから顧客IDで参照する形にすることで重複を排除できる。"},{"id":42,"cat":"データベース","topic":"分離レベルの選定(応用)","q":"厳密な整合性より処理速度を優先してよい、参照専用の集計バッチ処理に適したトランザクション分離レベルはどれか。","choices":[{"label":"ア","text":"REPEATABLE READ"},{"label":"イ","text":"いずれも同程度の性能"},{"label":"ウ","text":"SERIALIZABLE"},{"label":"エ","text":"READ COMMITTED"}],"correct":"エ","hint":"整合性要求が緩い処理では、より緩い分離レベルを選ぶことで並行性能を高められる。"},{"id":43,"cat":"データベース","topic":"インデックス設計の判断(応用)","q":"WHERE句で頻繁に絞り込み条件として指定される列があるが、検索に時間がかかっている。取るべき対策はどれか。","choices":[{"label":"ア","text":"トランザクション分離レベルを上げる"},{"label":"イ","text":"テーブルのパーティション数を減らす"},{"label":"ウ","text":"その列にインデックスを作成する"},{"label":"エ","text":"その列のデータ型を文字列型に変更する"}],"correct":"ウ","hint":"絞り込みに使われる列へのインデックス作成は検索性能改善の基本的な対策である。"},{"id":44,"cat":"データベース","topic":"バックアップ運用の設計(応用)","q":"毎日フルバックアップを取得するのはディスク容量的に厳しいが、障害時の復旧時間もできるだけ短くしたい。適した運用方式はどれか。","choices":[{"label":"ア","text":"週次フルバックアップと日次差分バックアップの組合せ"},{"label":"イ","text":"バックアップを取得しない"},{"label":"ウ","text":"毎日フルバックアップのみ"},{"label":"エ","text":"月次フルバックアップのみ"}],"correct":"ア","hint":"差分バックアップにより容量を抑えつつ、復旧に必要なバックアップ数も少なく抑えられる。"},{"id":45,"cat":"データベース","topic":"JOIN方法の選定(応用)","q":"顧客テーブルの全顧客を対象に、注文実績のない顧客も含めて一覧表示したい(注文がない場合は該当項目をNULLにしたい)。適した結合方法はどれか。","choices":[{"label":"ア","text":"INNER JOIN"},{"label":"イ","text":"LEFT OUTER JOIN"},{"label":"ウ","text":"CROSS JOIN"},{"label":"エ","text":"RIGHT OUTER JOIN(顧客テーブルが右側の場合を除く)"}],"correct":"イ","hint":"左側(顧客テーブル)の全行を残しつつ、一致しない場合はNULLで補う結合方法。"},{"id":46,"cat":"データベース","topic":"デッドロックへの対処(応用)","q":"2つのトランザクションが互いに相手のロック解放を待ち続け、処理が進まなくなった。この状態への一般的な対処法はどれか。","choices":[{"label":"ア","text":"両方のトランザクションを永久に待機させる"},{"label":"イ","text":"データベースを再起動する"},{"label":"ウ","text":"一方のトランザクションを強制的にロールバックする"},{"label":"エ","text":"分離レベルを最も緩いものに変更する"}],"correct":"ウ","hint":"DBMSがデッドロックを検知し、いずれかのトランザクションを中断させて解消することが多い。"},{"id":47,"cat":"データベース","topic":"NoSQLデータベースの選定(応用)","q":"スキーマが頻繁に変わり、構造化されていないJSON形式のデータを柔軟に格納したい場合に適したデータベースはどれか。","choices":[{"label":"ア","text":"カラム指向DB"},{"label":"イ","text":"グラフDB"},{"label":"ウ","text":"リレーショナルDB(厳密なスキーマ)"},{"label":"エ","text":"ドキュメント指向DB"}],"correct":"エ","hint":"ドキュメント指向DBは項目構成の異なるデータも柔軟に格納できる。"},{"id":48,"cat":"データベース","topic":"重複登録防止の設計(応用)","q":"同じINSERT文を誤って2回実行してしまっても、重複したデータが登録されないようにしたい。有効な設計はどれか。","choices":[{"label":"ア","text":"対象の列にUNIQUE制約(一意制約)を設定する"},{"label":"イ","text":"インデックスを全て削除する"},{"label":"ウ","text":"トランザクション分離レベルを下げる"},{"label":"エ","text":"テーブルのパーティションを増やす"}],"correct":"ア","hint":"一意制約により、同一値の重複挿入をデータベース側で拒否できる。"},{"id":49,"cat":"データベース","topic":"パーティショニング活用の判断(応用)","q":"過去の古いログデータを定期的に一括削除する運用がある場合、削除処理を高速化するために有効なテーブル設計はどれか。","choices":[{"label":"ア","text":"インデックスを全て削除する"},{"label":"イ","text":"正規化をやめて非正規化する"},{"label":"ウ","text":"日付範囲でのパーティショニング"},{"label":"エ","text":"ハッシュ値によるパーティショニング"}],"correct":"ウ","hint":"期間単位でパーティションを分けておけば、古い期間のパーティションごと削除できる。"},{"id":50,"cat":"データベース","topic":"ACID特性の理解(応用)","q":"銀行口座間の送金処理において、出金と入金のどちらか一方だけが実行されてしまう状態を防ぐために必要なトランザクションの性質はどれか。","choices":[{"label":"ア","text":"独立性(Isolation)"},{"label":"イ","text":"一貫性(Consistency)"},{"label":"ウ","text":"永続性(Durability)"},{"label":"エ","text":"原子性(Atomicity)"}],"correct":"エ","hint":"処理全体が「全て実行されるか、全く実行されないか」のいずれかになることを保証する性質。"},{"id":51,"cat":"アルゴリズム・プログラミング","topic":"ソート手法の選定(応用)","q":"既にほぼ整列済みのデータに対して、少量の追加データだけを整列させたい場合に効率がよいソートはどれか。","choices":[{"label":"ア","text":"クイックソート(平均的な場合)"},{"label":"イ","text":"挿入ソート"},{"label":"ウ","text":"ヒープソート"},{"label":"エ","text":"マージソート"}],"correct":"イ","hint":"挿入ソートは整列済み部分が多いほど比較・移動回数が少なく効率的に動作する。"},{"id":52,"cat":"アルゴリズム・プログラミング","topic":"データ構造の選定(応用)","q":"直近に行った操作を優先して取り消せるようにしたい(Undo機能)場合に適したデータ構造はどれか。","choices":[{"label":"ア","text":"スタック"},{"label":"イ","text":"デック(両方向キュー、単純な場合)"},{"label":"ウ","text":"キュー"},{"label":"エ","text":"優先度付きキュー"}],"correct":"ア","hint":"LIFO(後入れ先出し)の性質により最新の操作から順に取り消せる。"},{"id":53,"cat":"アルゴリズム・プログラミング","topic":"データ構造の選定2(応用)","q":"受付順にタスクを公平に処理したい印刷ジョブの管理に適したデータ構造はどれか。","choices":[{"label":"ア","text":"ハッシュ表"},{"label":"イ","text":"スタック"},{"label":"ウ","text":"優先度付きキュー"},{"label":"エ","text":"キュー"}],"correct":"エ","hint":"FIFO(先入れ先出し)の性質により受付順の公平な処理を実現できる。"},{"id":54,"cat":"アルゴリズム・プログラミング","topic":"探索方法の選定(応用)","q":"要素数が非常に多いソート済みデータから特定の値を検索したい場合、最も効率がよい探索方法はどれか。","choices":[{"label":"ア","text":"ハッシュ探索(ソート不要な場合との比較)"},{"label":"イ","text":"二分探索"},{"label":"ウ","text":"番兵法を用いた線形探索"},{"label":"エ","text":"線形探索"}],"correct":"イ","hint":"整列済みデータであれば二分探索でO(log n)の効率的な検索ができる。"},{"id":55,"cat":"アルゴリズム・プログラミング","topic":"再帰実装のリスク回避(応用)","q":"非常に深い再帰呼び出しが必要な処理で、スタックオーバーフローのリスクを避けたい場合に検討すべき実装方針はどれか。","choices":[{"label":"ア","text":"反復(ループ)による実装への書き換え"},{"label":"イ","text":"引数の型をより大きな型に変更する"},{"label":"ウ","text":"関数名をより短くする"},{"label":"エ","text":"再帰の呼び出し回数を記録するログの追加"}],"correct":"ア","hint":"再帰は呼び出しのたびにスタックを消費するため、深い再帰では反復実装が安全な場合がある。"},{"id":56,"cat":"アルゴリズム・プログラミング","topic":"デザインパターンの選定(応用)","q":"通知を受け取りたいオブジェクトの数が実行時に増減する場合に、通知を送る側のコードを変更せずに対応したい。適したデザインパターンはどれか。","choices":[{"label":"ア","text":"Facadeパターン"},{"label":"イ","text":"Decoratorパターン"},{"label":"ウ","text":"Observerパターン"},{"label":"エ","text":"Singletonパターン"}],"correct":"ウ","hint":"監視対象の状態変化を、登録された複数のオブジェクトへ自動的に通知できる。"},{"id":57,"cat":"アルゴリズム・プログラミング","topic":"例外処理の設計(応用)","q":"ファイルの読み込み処理中に例外が発生する可能性があるが、成功・失敗にかかわらず必ずファイルハンドルを解放したい。適した構文はどれか。","choices":[{"label":"ア","text":"while文による繰返し処理のみ"},{"label":"イ","text":"グローバル変数によるフラグ管理のみ"},{"label":"ウ","text":"try-catch-finally(finally節でクローズ処理を行う)"},{"label":"エ","text":"if文による分岐のみ"}],"correct":"ウ","hint":"finally節は例外の有無にかかわらず必ず実行されるため、リソース解放処理に適している。"},{"id":58,"cat":"アルゴリズム・プログラミング","topic":"総称型の活用場面(応用)","q":"商品IDのように構造は同じだが、扱う商品カテゴリごとに型を分けて安全に扱いたい場合に有効な言語機能はどれか。","choices":[{"label":"ア","text":"ダックタイピング"},{"label":"イ","text":"ポリモーフィズム"},{"label":"ウ","text":"オーバーロード"},{"label":"エ","text":"ジェネリクス(総称型)"}],"correct":"エ","hint":"型を後から指定できるようにすることで、同じロジックを型ごとに重複して書かずに済む。"},{"id":59,"cat":"アルゴリズム・プログラミング","topic":"メモ化の活用場面(応用)","q":"同じ引数で何度も呼び出される再帰関数の実行時間が長くなっている。計算結果を保存して再計算を省き高速化する手法はどれか。","choices":[{"label":"ア","text":"メモ化"},{"label":"イ","text":"インライン展開"},{"label":"ウ","text":"ガベージコレクション"},{"label":"エ","text":"末尾呼び出し最適化"}],"correct":"ア","hint":"一度計算した結果をキャッシュし、同じ引数での再計算を省略する高速化手法。"},{"id":60,"cat":"アルゴリズム・プログラミング","topic":"探索アルゴリズムの選定(応用)","q":"SNS上で、ある人からある人までの最短の友人関係の連鎖(距離)を求めたい(全ての関係のコストは等しいとする)。適した探索方法はどれか。","choices":[{"label":"ア","text":"二分探索"},{"label":"イ","text":"幅優先探索(BFS)"},{"label":"ウ","text":"線形探索"},{"label":"エ","text":"深さ優先探索(DFS)"}],"correct":"イ","hint":"重みなしグラフにおける最短経路探索には幅優先探索が適している。"},{"id":61,"cat":"ソフトウェア・HI","topic":"アクセシビリティ対応(応用)","q":"視覚に障害のある利用者がスクリーンリーダーで画像の内容を理解できるようにするために設定すべきHTML属性はどれか。","choices":[{"label":"ア","text":"id属性"},{"label":"イ","text":"style属性"},{"label":"ウ","text":"alt属性(代替テキスト)"},{"label":"エ","text":"class属性"}],"correct":"ウ","hint":"画像の内容をテキストで説明することで、視覚的に画像を見られない利用者にも情報を伝えられる。"},{"id":62,"cat":"ソフトウェア・HI","topic":"フォーム離脱率の改善(応用)","q":"利用者が長いフォームの入力中にエラーに気づかず最後まで進んでしまい、送信時に一括でエラーが表示されて離脱率が高い。改善策はどれか。","choices":[{"label":"ア","text":"エラーメッセージを非表示にする"},{"label":"イ","text":"入力項目を全て必須にする"},{"label":"ウ","text":"送信ボタンを画面下部に固定する"},{"label":"エ","text":"各入力欄でその場にエラーを表示するインラインバリデーションの導入"}],"correct":"エ","hint":"入力の都度エラーに気づけるため、修正の手間と離脱を減らせる。"},{"id":63,"cat":"ソフトウェア・HI","topic":"マルチデバイス対応の設計(応用)","q":"スマートフォンとPCの両方で最適なレイアウトを、1つのコードベースで実現したい。適した設計手法はどれか。","choices":[{"label":"ア","text":"レスポンシブデザイン"},{"label":"イ","text":"フラットデザイン"},{"label":"ウ","text":"マテリアルデザイン"},{"label":"エ","text":"スキューモーフィズム"}],"correct":"ア","hint":"画面サイズに応じてレイアウトが自動的に最適化される設計手法。"},{"id":64,"cat":"ソフトウェア・HI","topic":"アーキテクチャ選定(応用)","q":"機能ごとに異なるチームが独立してリリースサイクルを回せるようにしたい、大規模なシステムの設計方針はどれか。","choices":[{"label":"ア","text":"パイプ&フィルタアーキテクチャ"},{"label":"イ","text":"マイクロサービスアーキテクチャ"},{"label":"ウ","text":"レイヤードアーキテクチャ"},{"label":"エ","text":"モノリシックアーキテクチャ"}],"correct":"イ","hint":"サービスごとに独立したデプロイ・技術選定・スケーリングが可能になる。"},{"id":65,"cat":"ソフトウェア・HI","topic":"API設計の選定(応用)","q":"クライアントが必要なデータ項目だけを指定して取得し、過剰なデータ転送を避けたい場合に適したAPI設計方式はどれか。","choices":[{"label":"ア","text":"GraphQL"},{"label":"イ","text":"SOAP"},{"label":"ウ","text":"gRPC"},{"label":"エ","text":"REST"}],"correct":"ア","hint":"クライアント側が取得したい項目をクエリで指定できる点がRESTと異なる。"},{"id":66,"cat":"ソフトウェア・HI","topic":"UI一貫性の維持(応用)","q":"複数のプロダクトチームが別々にUIを作った結果、ボタンの色や余白の使い方がばらばらになってしまった。再発防止に有効な取組みはどれか。","choices":[{"label":"ア","text":"各チームの裁量に完全に任せる"},{"label":"イ","text":"デザインシステムの導入"},{"label":"ウ","text":"デザインレビューの廃止"},{"label":"エ","text":"UIの共通化をあきらめる"}],"correct":"イ","hint":"色・タイポグラフィ・コンポーネントのルールを一元化し組織全体で一貫性を保つ。"},{"id":67,"cat":"ソフトウェア・HI","topic":"表示速度の改善(応用)","q":"スクロールしないと見えない画像まで初期表示時に全て読み込んでいて、ページの表示が遅い。改善策はどれか。","choices":[{"label":"ア","text":"画像の読み込みを並列数無制限にする"},{"label":"イ","text":"全ての画像を高解像度に変更する"},{"label":"ウ","text":"キャッシュを無効化する"},{"label":"エ","text":"レイジーローディングの導入"}],"correct":"エ","hint":"画面に表示される直前まで画像の読み込みを遅延させ、初期表示を高速化できる。"},{"id":68,"cat":"ソフトウェア・HI","topic":"障害の連鎖防止(応用)","q":"依存している外部APIの応答が不安定なとき、その影響がシステム全体に連鎖して波及するのを防ぎたい。適した設計パターンはどれか。","choices":[{"label":"ア","text":"リトライパターン(単純な再試行のみ)"},{"label":"イ","text":"APIゲートウェイ"},{"label":"ウ","text":"サーキットブレーカーパターン"},{"label":"エ","text":"キャッシュアサイドパターン"}],"correct":"ウ","hint":"障害が続く依存先への呼び出しを一時的に遮断し、連鎖障害を防ぐ。"},{"id":69,"cat":"ソフトウェア・HI","topic":"低コストなユーザビリティ評価(応用)","q":"リリース前に、比較的低コストで専門家の知見からUI上の問題点を洗い出したい。適した評価手法はどれか。","choices":[{"label":"ア","text":"ヒューリスティック評価"},{"label":"イ","text":"大規模ユーザビリティテスト"},{"label":"ウ","text":"カードソーティング法"},{"label":"エ","text":"A/Bテスト(本番運用が前提)"}],"correct":"ア","hint":"実際の利用者を集めずに、経験則に基づき専門家が問題点を指摘する手法。"},{"id":70,"cat":"ソフトウェア・HI","topic":"オフライン対応の実現(応用)","q":"ネットワーク接続が不安定な環境でも、アプリの基本機能を使えるようにしたい場合に有効な技術はどれか。","choices":[{"label":"ア","text":"CDNの導入のみ"},{"label":"イ","text":"サーバのスケールアップ"},{"label":"ウ","text":"データベースの正規化"},{"label":"エ","text":"Service Workerによるオフラインキャッシュ(PWA化)"}],"correct":"エ","hint":"バックグラウンドで動作するService Workerがオフライン時にもキャッシュからコンテンツを提供できる。"},{"id":71,"cat":"システム開発","topic":"開発モデルの選定(応用)","q":"要件がまだ固まっておらず、利用者の反応を見ながら少しずつ機能を作り込みたいプロジェクトに適した開発モデルはどれか。","choices":[{"label":"ア","text":"V字モデル"},{"label":"イ","text":"プロトタイピングモデル"},{"label":"ウ","text":"ビッグバンモデル(一括開発、非推奨)"},{"label":"エ","text":"ウォーターフォールモデル"}],"correct":"イ","hint":"早期に試作品を作り利用者の評価を得ながら要求を明確化していける。"},{"id":72,"cat":"システム開発","topic":"テスト技法の選定(応用)","q":"入力値の有効範囲の端(最小値・最大値付近)に不具合が集中する傾向がある場合、重点的に検証すべきテスト技法はどれか。","choices":[{"label":"ア","text":"デシジョンテーブルテスト"},{"label":"イ","text":"状態遷移テスト"},{"label":"ウ","text":"境界値分析"},{"label":"エ","text":"同値分割法"}],"correct":"ウ","hint":"有効範囲の境界付近に不具合が生じやすいという経験則に基づく技法。"},{"id":73,"cat":"システム開発","topic":"レビュー技法の選定(応用)","q":"限られた時間の中で、作成者主導により気軽にレビューを実施したい場合に適した手法はどれか。","choices":[{"label":"ア","text":"監査"},{"label":"イ","text":"ウォークスルー"},{"label":"ウ","text":"インスペクション"},{"label":"エ","text":"ペアプログラミング(レビューとは別の実践)"}],"correct":"イ","hint":"形式張らず、作成者が説明しながら誤りを発見していく比較的軽量なレビュー形式。"},{"id":74,"cat":"システム開発","topic":"デプロイ戦略の選定(応用)","q":"新バージョンに問題があった場合、即座に旧環境へ切り戻せるようにしたい。適したデプロイ手法はどれか。","choices":[{"label":"ア","text":"ブルーグリーンデプロイメント"},{"label":"イ","text":"ビッグバンリリース"},{"label":"ウ","text":"手動での個別サーバ更新"},{"label":"エ","text":"ローリングアップデートのみ"}],"correct":"ア","hint":"新旧2つの環境を用意し、切替によって瞬時にリリース・切戻しができる。"},{"id":75,"cat":"システム開発","topic":"スクラムイベントの選定(応用)","q":"毎日15分程度、チームで進捗状況と障害となっていることを短時間で共有したい場合に行うスクラムイベントはどれか。","choices":[{"label":"ア","text":"レトロスペクティブ"},{"label":"イ","text":"スプリントレビュー"},{"label":"ウ","text":"デイリースクラム"},{"label":"エ","text":"スプリントプランニング"}],"correct":"ウ","hint":"短時間で状況を共有し、障害を早期に発見することを目的とする。"},{"id":76,"cat":"システム開発","topic":"見積り手法の選定(応用)","q":"過去の類似案件のデータが乏しい新規性の高いプロジェクトで、複数の専門家の意見を匿名で収束させながら見積りたい。適した手法はどれか。","choices":[{"label":"ア","text":"類推見積り法"},{"label":"イ","text":"ボトムアップ見積り法"},{"label":"ウ","text":"パラメトリック見積り法"},{"label":"エ","text":"デルファイ法"}],"correct":"エ","hint":"匿名の専門家グループへの質問と回答の集約を繰り返し、意見を収束させていく技法。"},{"id":77,"cat":"システム開発","topic":"モジュール設計の改善(応用)","q":"1つのモジュールが複数の無関係な機能を持ち、変更のたびに影響範囲の特定が困難になっている。改善すべき設計指標はどれか。","choices":[{"label":"ア","text":"結合度を高める設計への変更"},{"label":"イ","text":"コメント量を増やすことのみ"},{"label":"ウ","text":"凝集度を高める設計への変更"},{"label":"エ","text":"モジュール数を減らすことのみ"}],"correct":"ウ","hint":"モジュール内の要素を単一の目的に集中させる(凝集度を高める)ことで保守性が向上する。"},{"id":78,"cat":"システム開発","topic":"CI/CD導入の効果(応用)","q":"コードの変更のたびに手動でビルド・テストを行っており、リリースに時間がかかっている。改善策はどれか。","choices":[{"label":"ア","text":"リリース頻度を減らす"},{"label":"イ","text":"コードレビューを廃止する"},{"label":"ウ","text":"手動テストの人数を増やす"},{"label":"エ","text":"CI/CDパイプラインの導入"}],"correct":"エ","hint":"変更検知から自動的にビルド・テスト・デプロイまでを一連の流れで実行できる。"},{"id":79,"cat":"システム開発","topic":"トレーサビリティの確保(応用)","q":"要件定義の内容が最終的な実装のどの部分に反映されているかを追跡できず、変更時の影響範囲把握に苦労している。有効な取組みはどれか。","choices":[{"label":"ア","text":"要件と実装の対応関係(トレーサビリティ)を管理する"},{"label":"イ","text":"コメントを全て削除する"},{"label":"ウ","text":"設計書を作成しない"},{"label":"エ","text":"要件定義書を作成しない"}],"correct":"ア","hint":"要件から設計・実装・テストまでの対応関係を追跡できると、影響範囲の特定が容易になる。"},{"id":80,"cat":"システム開発","topic":"品質状況の可視化(応用)","q":"テスト工程で検出されるバグの件数がなかなか収束せず、リリース時期の判断材料が欲しい。活用すべき手法はどれか。","choices":[{"label":"ア","text":"ガントチャートの作成のみ"},{"label":"イ","text":"信頼度成長曲線によるバグ検出状況の可視化"},{"label":"ウ","text":"パレート図の作成のみ"},{"label":"エ","text":"特性要因図の作成のみ"}],"correct":"イ","hint":"累積バグ検出数の推移をグラフ化し、収束傾向から品質状況を判断できる。"},{"id":81,"cat":"プロジェクトマネジメント","topic":"スケジュール短縮技法の選定(応用)","q":"追加コストをかけずに、本来は順番に行う設計とコーディングの一部を並行して進めることで工期を短縮したい。適した技法はどれか。","choices":[{"label":"ア","text":"クリティカルチェーン法"},{"label":"イ","text":"資源の山積み"},{"label":"ウ","text":"ファストトラッキング"},{"label":"エ","text":"クラッシング"}],"correct":"ウ","hint":"クラッシングは要員追加等コストをかけて短縮する点でファストトラッキングと異なる。"},{"id":82,"cat":"プロジェクトマネジメント","topic":"リスク対応戦略の選定(応用)","q":"海外拠点の為替変動リスクを、保険や契約によって第三者に移転したい。適したリスク対応戦略はどれか。","choices":[{"label":"ア","text":"軽減"},{"label":"イ","text":"回避"},{"label":"ウ","text":"受容"},{"label":"エ","text":"転嫁"}],"correct":"エ","hint":"リスク自体は消えないが自組織が直接負う影響を軽減できる。"},{"id":83,"cat":"プロジェクトマネジメント","topic":"EVMによる状況判断(応用)","q":"あるプロジェクトの出来高(EV)が計画値(PV)を下回っている場合、スケジュール上どのような状態と判断できるか。","choices":[{"label":"ア","text":"計画より進捗が遅れている"},{"label":"イ","text":"計画よりコストがかかっている"},{"label":"ウ","text":"品質に問題が発生している"},{"label":"エ","text":"計画より進捗が進んでいる"}],"correct":"ア","hint":"EVがPVを下回るとスケジュール差異(SV=EV-PV)が負の値になり、遅延を示す。"},{"id":84,"cat":"プロジェクトマネジメント","topic":"ステークホルダー対応方針の選定(応用)","q":"影響力は大きいが関心度が低いステークホルダーへの対応方針として適切なものはどれか。","choices":[{"label":"ア","text":"完全に監視のみで対応する"},{"label":"イ","text":"満足させる程度の必要最小限の情報提供にとどめる"},{"label":"ウ","text":"関与自体を一切行わない"},{"label":"エ","text":"密接に管理し常に最優先で関与する"}],"correct":"イ","hint":"影響力・関心度のマトリクスに基づき、関与の濃淡を使い分けることが有効とされる。"},{"id":85,"cat":"プロジェクトマネジメント","topic":"プロジェクト組織形態の選定(応用)","q":"プロジェクトマネージャーに強い権限を持たせ、機能部門の意向より優先して意思決定を進めたい場合に適した組織形態はどれか。","choices":[{"label":"ア","text":"機能別組織"},{"label":"イ","text":"強いマトリクス組織"},{"label":"ウ","text":"弱いマトリクス組織"},{"label":"エ","text":"完全な機能別組織(重複表現の回避)"}],"correct":"イ","hint":"強いマトリクス組織ではプロジェクトマネージャー側の権限がより強く設定される。"},{"id":86,"cat":"プロジェクトマネジメント","topic":"スコープクリープへの対処(応用)","q":"現場の判断だけで仕様変更が積み重なり、当初のスコープから大きく逸脱してしまった。再発防止に必要な取組みはどれか。","choices":[{"label":"ア","text":"統合変更管理プロセスの徹底"},{"label":"イ","text":"スコープ記述書の作成をやめる"},{"label":"ウ","text":"現場判断の範囲をさらに広げる"},{"label":"エ","text":"変更要求を一切受け付けない"}],"correct":"ア","hint":"変更要求を正式なプロセスで評価・承認する仕組みがスコープクリープを防ぐ。"},{"id":87,"cat":"プロジェクトマネジメント","topic":"品質改善の優先順位付け(応用)","q":"発生した不具合の大部分が、ごく少数の原因に集中していることが分かった。重点的に対処すべき原因を特定するために有効な図はどれか。","choices":[{"label":"ア","text":"散布図"},{"label":"イ","text":"特性要因図"},{"label":"ウ","text":"管理図"},{"label":"エ","text":"パレート図"}],"correct":"エ","hint":"発生件数の多い順に並べることで、全体の大部分を占める少数の要因を特定できる。"},{"id":88,"cat":"プロジェクトマネジメント","topic":"教訓の蓄積(応用)","q":"プロジェクト完了後、実績と当初見積りの差異やその原因をチームで整理し、次のプロジェクトに活かしたい。取るべき取組みはどれか。","choices":[{"label":"ア","text":"プロジェクト資料を全て破棄する"},{"label":"イ","text":"次回も同じ見積り手法を無条件に踏襲する"},{"label":"ウ","text":"レッスンズラーンド(教訓)の記録・共有"},{"label":"エ","text":"担当者の異動のみで対応する"}],"correct":"ウ","hint":"組織のプロセス資産として蓄積し、将来の見積り精度向上等に役立てる。"},{"id":89,"cat":"サービスマネジメント・監査","topic":"根本原因への対処(応用)","q":"同じ障害が繰り返し発生しているが、根本原因の特定ができていない。取るべき管理プロセスはどれか。","choices":[{"label":"ア","text":"変更管理のみ"},{"label":"イ","text":"インシデント管理のみ"},{"label":"ウ","text":"需要管理"},{"label":"エ","text":"問題管理(根本原因分析)"}],"correct":"エ","hint":"インシデント管理が迅速な復旧を優先するのに対し、問題管理は根本解決を目指す。"},{"id":90,"cat":"サービスマネジメント・監査","topic":"SLA達成状況の継続管理(応用)","q":"合意した稼働率目標を継続的に達成できているかを監視し、未達の場合は改善策を講じたい。該当する活動はどれか。","choices":[{"label":"ア","text":"需要管理のみ"},{"label":"イ","text":"SLM(サービスレベル管理)"},{"label":"ウ","text":"SLAの締結のみ"},{"label":"エ","text":"キャパシティ管理のみ"}],"correct":"イ","hint":"SLAで合意した内容が実際に達成されているかを継続的に監視・改善する活動。"},{"id":91,"cat":"サービスマネジメント・監査","topic":"変更管理プロセスの活用(応用)","q":"本番環境への変更によるリスクを事前に評価し、関係者の合意を得てから実施したい。適した仕組みはどれか。","choices":[{"label":"ア","text":"担当者の独断による即時実施"},{"label":"イ","text":"事後報告のみで完結させる運用"},{"label":"ウ","text":"CAB(変更諮問委員会)による事前審議"},{"label":"エ","text":"変更の記録を残さない運用"}],"correct":"ウ","hint":"変更のリスクと影響を関係者が集まり事前に審議する仕組み。"},{"id":92,"cat":"サービスマネジメント・監査","topic":"事業継続の優先順位付け(応用)","q":"災害発生時、どの業務からどの順序で復旧させるべきかの優先順位を事前に整理しておきたい。実施すべき活動はどれか。","choices":[{"label":"ア","text":"BIA(事業影響度分析)"},{"label":"イ","text":"ペネトレーションテストのみ"},{"label":"ウ","text":"リスクアセスメントのみ"},{"label":"エ","text":"脆弱性診断のみ"}],"correct":"ア","hint":"業務中断による影響を分析し、RTO・RPOの根拠を得る活動。"},{"id":93,"cat":"サービスマネジメント・監査","topic":"内部統制の改善(応用)","q":"特定の担当者が申請から承認まで一人で完結できてしまい、不正のリスクがある。改善すべき統制はどれか。","choices":[{"label":"ア","text":"パスワードポリシーの強化のみ"},{"label":"イ","text":"担当者の増員のみ"},{"label":"ウ","text":"監視カメラの増設のみ"},{"label":"エ","text":"職務分掌の徹底"}],"correct":"エ","hint":"承認者と実行者を分けることで相互牽制を働かせる統制。"},{"id":94,"cat":"サービスマネジメント・監査","topic":"監査手続の選定(応用)","q":"在庫管理システムの入力データが正しく計算処理されているかを検証したい。監査人自らが同じ計算を再度行う監査手続はどれか。","choices":[{"label":"ア","text":"閲覧"},{"label":"イ","text":"再実施"},{"label":"ウ","text":"質問"},{"label":"エ","text":"分析的手続"}],"correct":"イ","hint":"システムの計算ロジックの検証等、より強い心証を得られる監査手続とされる。"},{"id":95,"cat":"サービスマネジメント・監査","topic":"問い合わせ件数の削減施策(応用)","q":"よくある問い合わせ内容への対応を利用者自身で完結できるようにして、問い合わせ件数を減らしたい。有効な施策はどれか。","choices":[{"label":"ア","text":"サービスデスクの人員を減らすのみ"},{"label":"イ","text":"問い合わせ窓口を廃止する"},{"label":"ウ","text":"セルフサービスポータル・FAQの整備"},{"label":"エ","text":"問い合わせ受付時間を短縮するのみ"}],"correct":"ウ","hint":"定型的な問い合わせをポータル側で解決し、人手対応の負荷を減らす狙いがある。"},{"id":96,"cat":"サービスマネジメント・監査","topic":"監査意見の選定(応用)","q":"監査の結果、財務諸表の一部に軽微な問題はあるが全体としては適正と判断できる場合の監査意見はどれか。","choices":[{"label":"ア","text":"限定付適正意見"},{"label":"イ","text":"意見不表明"},{"label":"ウ","text":"無限定適正意見"},{"label":"エ","text":"不適正意見"}],"correct":"ア","hint":"重要な虚偽表示や監査範囲の制約があっても、影響が全体に及ぶほど重大でない場合に表明される。"},{"id":97,"cat":"経営・戦略・法務","topic":"事業戦略の選定(応用)","q":"資金力で大手企業に劣る中小企業が、大手が参入しない特定のニーズに特化して事業展開したい。適した戦略はどれか。","choices":[{"label":"ア","text":"コストリーダーシップ戦略"},{"label":"イ","text":"ブルーオーシャン戦略(市場創造が主眼)"},{"label":"ウ","text":"垂直統合戦略"},{"label":"エ","text":"ニッチ戦略"}],"correct":"エ","hint":"限られた資源を狭い市場に集中させることで大手との直接競合を避けられる。"},{"id":98,"cat":"経営・戦略・法務","topic":"財務健全性の評価(応用)","q":"ある企業の自己資本比率が業界平均より極端に低い場合、一般的に懸念される点はどれか。","choices":[{"label":"ア","text":"財務的な安全性が低く、負債への依存度が高い"},{"label":"イ","text":"短期的な支払能力が非常に高い"},{"label":"ウ","text":"売上高が急増している"},{"label":"エ","text":"在庫の回転効率が良い"}],"correct":"ア","hint":"自己資本比率が低いほど負債の割合が大きく、財務的な安定性の面でリスクが高いとされる。"},{"id":99,"cat":"経営・戦略・法務","topic":"損益分岐点の計算(応用)","q":"固定費が月100万円、変動費率が60%の事業における、損益分岐点となる月間売上高はどれか。","choices":[{"label":"ア","text":"160万円"},{"label":"イ","text":"400万円"},{"label":"ウ","text":"250万円"},{"label":"エ","text":"166万円"}],"correct":"ウ","hint":"固定費÷(1-変動費率)=100万円÷0.4=250万円として求められる。"},{"id":100,"cat":"経営・戦略・法務","topic":"知的財産権の適用判断(応用)","q":"自社開発したソフトウェアのソースコードを、他社に無断でコピーされないよう権利を主張したい。関係する法律はどれか。","choices":[{"label":"ア","text":"特許法"},{"label":"イ","text":"著作権法"},{"label":"ウ","text":"意匠法"},{"label":"エ","text":"実用新案法"}],"correct":"イ","hint":"ソースコードは創作的な表現として著作権法上の保護対象となる。"},{"id":101,"cat":"経営・戦略・法務","topic":"消費者保護制度の適用(応用)","q":"訪問販売で購入した高額商品について、契約後一定期間内であれば無条件で契約を解除できる制度はどれか。","choices":[{"label":"ア","text":"独占禁止法上の規制"},{"label":"イ","text":"クーリングオフ制度"},{"label":"ウ","text":"景品表示法上の規制"},{"label":"エ","text":"製造物責任(PL法)"}],"correct":"イ","hint":"特定商取引法に基づき、一定の取引類型で消費者に契約解除の権利を認める制度。"},{"id":102,"cat":"経営・戦略・法務","topic":"個人情報の目的外利用への対応(応用)","q":"取得した顧客のメールアドレスを、当初の利用目的以外の別サービスの広告配信に利用したい場合、必要な対応はどれか。","choices":[{"label":"ア","text":"監督官庁への届出のみで足りる"},{"label":"イ","text":"特に手続きは不要でそのまま利用してよい"},{"label":"ウ","text":"利用目的の変更について本人の同意を得る、または通知・公表する"},{"label":"エ","text":"メールアドレスを暗号化すれば自由に利用してよい"}],"correct":"ウ","hint":"個人情報保護法上、取得時の利用目的の範囲を超えて利用する場合は原則として本人の同意等が必要となる。"},{"id":103,"cat":"経営・戦略・法務","topic":"PPMによる事業分類(応用)","q":"ある事業が「市場成長率は高いが自社の市場占有率は低い」状態にある場合、PPMにおける分類はどれか。","choices":[{"label":"ア","text":"負け犬"},{"label":"イ","text":"花形"},{"label":"ウ","text":"金のなる木"},{"label":"エ","text":"問題児"}],"correct":"エ","hint":"成長率は高いがシェアが低いため今後の資源投入判断が重要になる分類とされる。"},{"id":104,"cat":"経営・戦略・法務","topic":"意思決定手法の選定(応用)","q":"新規事業への投資判断において、想定される複数のシナリオごとの発生確率と利益を樹形図で整理し、期待値で比較したい。適した分析手法はどれか。","choices":[{"label":"ア","text":"デシジョンツリー分析"},{"label":"イ","text":"SWOT分析"},{"label":"ウ","text":"PPM"},{"label":"エ","text":"バリューチェーン分析"}],"correct":"ア","hint":"各分岐の確率と利益から期待値を算出し、不確実性を伴う意思決定を支援する。"},{"id":105,"cat":"経営・戦略・法務","topic":"労使協定の理解(応用)","q":"社員に法定労働時間を超えて残業させる必要がある場合、事前に労働基準監督署へ届け出るべき労使協定はどれか。","choices":[{"label":"ア","text":"労働契約書"},{"label":"イ","text":"就業規則"},{"label":"ウ","text":"36協定(サブロク協定)"},{"label":"エ","text":"賃金規程"}],"correct":"ウ","hint":"労働基準法第36条に基づく協定であることが名称の由来。"},{"id":106,"cat":"経営・戦略・法務","topic":"独占禁止法の適用場面(応用)","q":"取引先に対して優越的な立場を利用し、不当な値下げを強要した場合に問題となる法律とその行為類型はどれか。","choices":[{"label":"ア","text":"独占禁止法における優越的地位の濫用"},{"label":"イ","text":"景品表示法における不当表示"},{"label":"ウ","text":"下請法における支払遅延"},{"label":"エ","text":"特定商取引法における不実告知"}],"correct":"ア","hint":"取引上優位な立場を利用して相手方に不当な不利益を強いる行為を規制する。"},{"id":107,"cat":"経営・戦略・法務","topic":"資金繰りの理解(応用)","q":"会計上は利益が出ているにもかかわらず、手元の現金が不足して支払いができなくなる状態を何と呼ぶか。","choices":[{"label":"ア","text":"債務超過"},{"label":"イ","text":"資本欠損"},{"label":"ウ","text":"赤字経営"},{"label":"エ","text":"黒字倒産"}],"correct":"エ","hint":"利益と実際の現金の動きにずれが生じることで発生しうる状態である。"},{"id":108,"cat":"経営・戦略・法務","topic":"市場創造戦略の選定(応用)","q":"競争の激しい既存市場を避け、価値を高めながらコストを下げることで競合のいない新たな市場を切り開きたい。適した戦略はどれか。","choices":[{"label":"ア","text":"コストリーダーシップ戦略"},{"label":"イ","text":"ブルーオーシャン戦略"},{"label":"ウ","text":"ニッチ戦略"},{"label":"エ","text":"レッドオーシャン戦略"}],"correct":"イ","hint":"「価値革新」により競争のない新市場空間の創造を志向する戦略。"}];

const C = {
  bg:"#0d1117", surface:"#161b22", surface2:"#1c2330", border:"#30363d",
  accent:"#58a6ff", green:"#3fb950", red:"#f85149", warn:"#d29922",
  text:"#e6edf3", muted:"#8b949e",
};

const s = {
  app:{ background:C.bg, minHeight:"100vh", padding:"20px 14px", fontFamily:"'Noto Sans JP',sans-serif", color:C.text },
  container:{ maxWidth:600, margin:"0 auto" },
  header:{ textAlign:"center", marginBottom:28 },
  h1:{ fontFamily:"monospace", fontSize:13, color:C.accent, letterSpacing:".1em", textTransform:"uppercase", marginBottom:4 },
  sub:{ color:C.muted, fontSize:12 },
  card:{ background:C.surface, border:`1px solid ${C.border}`, borderRadius:12, padding:20, marginBottom:14 },
  row:{ display:"flex", gap:8, flexWrap:"wrap", marginBottom:16 },
  chip:(a)=>({ padding:"5px 12px", background:a?"rgba(88,166,255,.1)":C.surface, border:`1px solid ${a?C.accent:C.border}`, borderRadius:20, color:a?C.accent:C.muted, fontSize:12, cursor:"pointer", fontFamily:"inherit" }),
  btn:(color=C.accent, outline=false)=>({ padding:"10px 20px", background:outline?"none":color, border:`1px solid ${color}`, borderRadius:8, color:outline?color:"#0d1117", fontFamily:"inherit", fontWeight:700, fontSize:14, cursor:"pointer" }),
  choiceBtn:(state)=>({
    width:"100%", padding:"11px 14px",
    background:state==="correct"?"rgba(63,185,80,.1)":state==="wrong"?"rgba(248,81,73,.1)":C.surface2,
    border:`1px solid ${state==="correct"?C.green:state==="wrong"?C.red:C.border}`,
    borderRadius:8, color:state==="correct"?C.green:state==="wrong"?C.red:C.text,
    fontFamily:"inherit", fontSize:16, textAlign:"left", cursor:state?"default":"pointer",
    display:"flex", gap:10, alignItems:"flex-start", lineHeight:1.5, marginBottom:7,
  }),
  label:{ fontFamily:"monospace", fontSize:14, color:C.muted, flexShrink:0, paddingTop:1 },
  fb:(ok)=>({ marginTop:14, padding:"12px 14px", borderRadius:8, fontSize:15, lineHeight:1.7, background:ok?"rgba(63,185,80,.08)":"rgba(248,81,73,.08)", border:`1px solid ${ok?"rgba(63,185,80,.3)":"rgba(248,81,73,.3)"}`, color:ok?C.green:C.red }),
  hintBox:{ marginTop:10, padding:"10px 12px", background:"rgba(255,255,255,.03)", border:`1px solid ${C.border}`, borderRadius:6, fontSize:14, color:C.muted, lineHeight:1.6 },
  hintLabel:{ fontSize:11, fontFamily:"monospace", color:C.accent, textTransform:"uppercase", letterSpacing:".05em", marginBottom:3 },
  progress:{ height:3, background:C.border, borderRadius:2, marginBottom:16, overflow:"hidden" },
  bar:(pct)=>({ height:"100%", background:C.accent, borderRadius:2, width:`${pct}%`, transition:"width .3s" }),
  meta:{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:12 },
  catTag:{ fontSize:11, padding:"2px 7px", background:"rgba(88,166,255,.1)", color:C.accent, borderRadius:4, fontFamily:"monospace" },
  qnum:{ fontSize:13, color:C.muted, fontFamily:"monospace", marginBottom:6 },
  qtext:{ fontSize:17, fontWeight:500, lineHeight:1.65, marginBottom:18 },
  tabs:{ display:"flex", gap:4, marginBottom:20, background:C.surface, padding:4, borderRadius:8, border:`1px solid ${C.border}` },
  tabBtn:(a)=>({ flex:1, padding:8, background:a?C.surface2:"none", border:"none", color:a?C.text:C.muted, fontFamily:"inherit", fontSize:15, borderRadius:6, cursor:"pointer", fontWeight:a?700:400 }),
  reviewItem:{ background:C.surface, border:`1px solid ${C.border}`, borderLeft:`3px solid ${C.red}`, borderRadius:8, padding:14, marginBottom:10 },
  sectionTitle:{ fontSize:11, color:C.muted, fontFamily:"monospace", textTransform:"uppercase", letterSpacing:".06em", margin:"20px 0 8px" },
  catBarRow:{ display:"flex", alignItems:"center", gap:8, marginBottom:8, background:C.surface, border:`1px solid ${C.border}`, borderRadius:8, padding:"9px 11px" },
  statBox:{ background:C.surface, border:`1px solid ${C.border}`, borderRadius:10, padding:"12px 8px", textAlign:"center", flex:1 },
  statNum:{ fontFamily:"monospace", fontSize:22, fontWeight:600, color:C.accent },
  statLabel:{ fontSize:11, color:C.muted, marginTop:2 },
  analysisBox:{ background:C.surface2, border:`1px solid ${C.border}`, borderRadius:10, padding:16, fontSize:13, lineHeight:1.8, color:C.text, whiteSpace:"pre-wrap" },
  spinner:{ display:"inline-block", width:16, height:16, border:`2px solid ${C.border}`, borderTop:`2px solid ${C.accent}`, borderRadius:"50%", animation:"spin 0.8s linear infinite", verticalAlign:"middle" },
  errBox:{ padding:"12px 14px", background:"rgba(248,81,73,.08)", border:`1px solid rgba(248,81,73,.3)`, borderRadius:8, color:C.red, fontSize:13, marginTop:12 },
  copyBox:{ background:C.surface2, border:`1px solid ${C.border}`, borderRadius:8, padding:12, fontSize:12, fontFamily:"monospace", color:C.muted, lineHeight:1.7, whiteSpace:"pre-wrap", wordBreak:"break-all", marginTop:8, maxHeight:160, overflowY:"auto" },
  copyBtn:(copied)=>({ padding:"8px 16px", background:copied?"rgba(63,185,80,.15)":"none", border:`1px solid ${copied?C.green:C.border}`, borderRadius:6, color:copied?C.green:C.muted, fontFamily:"inherit", fontSize:12, cursor:"pointer", transition:"all .2s" }),
  stockBadge:(n)=>({ display:"inline-block", padding:"2px 8px", borderRadius:10, fontSize:12, fontFamily:"monospace", fontWeight:700, background:n>=20?"rgba(63,185,80,.15)":n>0?"rgba(210,153,34,.15)":"rgba(248,81,73,.15)", color:n>=20?C.green:n>0?C.warn:C.red }),
};

function rateColor(p){ return p>=80?C.green:p>=50?C.warn:C.red; }
function shuffle(arr){ const a=[...arr]; for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; }

async function callClaude(messages, system){
  const apiKey = process.env.REACT_APP_ANTHROPIC_KEY || "";
  const headers = {"Content-Type":"application/json"};
  if(apiKey) headers["x-api-key"] = apiKey;
  const res = await fetch("https://api.anthropic.com/v1/messages",{
    method:"POST", headers,
    body:JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:1000, system, messages }),
  });
  const data = await res.json();
  return data.content?.map(b=>b.text||"").join("")||"";
}

async function analyzeResults(questions, answers, catStats){
  const log = questions.map((q,i)=>`Q${i+1}[${q.cat}/${q.topic}]: ${answers[i]===q.correct?"○":"✗"}`).join("\n");
  const stats = Object.entries(catStats).map(([c,s])=>`${c}: ${Math.round(s.ok/s.total*100)}% (${s.ok}/${s.total}問)`).join("\n");
  const system = `あなたは基本情報技術者試験の学習コーチです。結果を分析し①弱点②強み・弱みの評価③次の学習ステップを250〜350字で返してください。`;
  return await callClaude([{role:"user",content:`【回答】\n${log}\n\n【累計】\n${stats}`}], system);
}

function ReviewCopyBox({ missedList, lifetimeByCat }){
  const [copied, setCopied] = useState(false);

  const buildText = useCallback(()=>{
    const now = new Date();
    const ds = `${now.getFullYear()}/${now.getMonth()+1}/${now.getDate()} ${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
    const catGroup = {};
    missedList.forEach(q=>{ if(!catGroup[q.cat]) catGroup[q.cat]=[]; catGroup[q.cat].push(q); });
    const lines = [
      `📝 FE科目A 復習リスト ${ds}`,
      `間違えた問題: ${missedList.length}問`,
      `---`,
    ];
    Object.entries(catGroup).forEach(([cat, qs])=>{
      // 分野別の正解率は「累計(生涯)」の実績を使う。今回の周回だけの一時的な
      // 集計だと、ページを開き直した直後は0%になってしまうため。
      const st = lifetimeByCat[cat];
      const pct = st && st.total>0 ? Math.round(st.ok/st.total*100) : null;
      const pctLabel = pct===null ? "累計データなし" : `累計正解率 ${pct}%`;
      lines.push(`\n■ ${cat}（${pctLabel}）`);
      qs.forEach((q,i)=>{
        const cc = q.choices.find(c=>c.label===q.correct);
        lines.push(`Q: ${q.q}`);
        lines.push(`A: ${q.correct}. ${cc?.text}`);
        lines.push(`解説: ${q.hint}`);
        if(i < qs.length-1) lines.push("");
      });
    });
    return lines.join("\n");
  },[missedList, lifetimeByCat]);

  const handleCopy = useCallback(()=>{
    const text = buildText();
    navigator.clipboard.writeText(text).then(()=>{
      setCopied(true); setTimeout(()=>setCopied(false), 2000);
    }).catch(()=>{
      const ta = document.getElementById("review-copy-area");
      if(ta){ ta.value=text; ta.select(); document.execCommand("copy"); setCopied(true); setTimeout(()=>setCopied(false),2000); }
    });
  },[buildText]);

  return(
    <div style={{background:C.surface2, border:`1px solid ${C.border}`, borderRadius:10, padding:14, marginBottom:16}}>
      <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8}}>
        <div style={{fontSize:12, color:C.muted}}>📋 復習リストをチャットに貼る</div>
        <button style={s.copyBtn(copied)} onClick={handleCopy}>
          {copied ? "✓ コピーしました" : "コピー"}
        </button>
      </div>
      <div style={{fontSize:11, color:C.muted, lineHeight:1.6}}>
        間違えた問題の正解・解説を分野別にまとめたテキストをコピーできます。<br/>
        コピー後このチャットに貼り付けると履歴として残ります。
      </div>
      <textarea id="review-copy-area" readOnly value={buildText()}
        style={{position:"absolute", left:"-9999px", top:0}}/>
    </div>
  );
}

export default function App(){
  const [tab, setTab] = useState("quiz");
  const [cat, setCat] = useState("すべて");
  const [weakMode, setWeakMode] = useState(false);
  const [weakIds, setWeakIds] = useState([]);
  const [phase, setPhase] = useState("idle");
  const [usedIds, setUsedIds] = useState([]);
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [qIdx, setQIdx] = useState(0);
  const [chosen, setChosen] = useState(null);
  const [showFb, setShowFb] = useState(false);
  const [analysis, setAnalysis] = useState("");
  const [allHistory, setAllHistory] = useState([]);
  const [savedSessions, setSavedSessions] = useState([]);
  const [lifetime, setLifetime] = useState({totalAnswered:0,totalCorrect:0,byCat:{}});
  const [missedList, setMissedList] = useState([]);
  const [catStats, setCatStats] = useState({});
  const [copyText, setCopyText] = useState("");
  const [copied, setCopied] = useState(false);
  const [progressLoading, setProgressLoading] = useState(true);
  const [progressError, setProgressError] = useState("");

  // 起動時にlocalStorageから進捗・履歴を復元
  useEffect(()=>{
    // 問題内容が(id構成として)前回と変わっていないかを確認する。
    // 変わっていた場合、古い周回進捗・復習リストは今の問題内容と対応しなくなるため
    // 自動的にクリアする(生涯累計・セッション履歴は問題内容が変わっても意味を持つため維持する)。
    const currentSignature = ALL_QUESTIONS.length + ":" + ALL_QUESTIONS.map(q=>q.id).join(",");
    let storedSignature = null;
    try{ storedSignature = localStorage.getItem(LS_QVERSION); }catch(e){}
    const contentChanged = storedSignature !== null && storedSignature !== currentSignature;
    if(contentChanged){
      try{
        localStorage.removeItem(LS_USED);
        localStorage.removeItem(LS_CYCLE);
        localStorage.removeItem(LS_MISSED);
      }catch(e){}
    }
    try{ localStorage.setItem(LS_QVERSION, currentSignature); }catch(e){}

    const ids = contentChanged ? [] : store.loadIds().filter(id => ALL_QUESTIONS.some(q=>q.id===id));
    if(ids.length > 0){
      setUsedIds(ids);
      setProgressError(`✓ 今の周回で${ids.length}問に解答済み（残り${ALL_QUESTIONS.length-ids.length}問／全${ALL_QUESTIONS.length}問）`);
    } else if(contentChanged){
      setProgressError(`問題の内容が更新されました。周回・復習リストを初期化しました（累計成績は引き続き保持されています）。`);
    }
    // 過去のセッション履歴を復元(直近最大100件、表示専用)
    const saved = store.loadSessions();
    if(saved.length > 0) setSavedSessions(saved);
    // 生涯累計を復元(こちらは間引かれない真の累計。問題内容が変わっても維持する)
    setLifetime(store.loadLifetime());
    // 復習リストを復元
    if(!contentChanged){
      const missed = store.loadMissed();
      if(missed.length > 0) setMissedList(missed);
    }
    // 今回の周回成績を復元(リロードしても消えない。usedIdsが空＝新しい周回なら
    // 古いcycleデータが残っていても無視して空から始める)
    if(ids.length > 0){
      const cyc = store.loadCycle();
      if(cyc.history && cyc.history.length > 0) setAllHistory(cyc.history);
      if(cyc.catStats) setCatStats(cyc.catStats);
    } else {
      store.clearCycle();
    }
    setProgressLoading(false);
  },[]); // eslint-disable-line

  // 残り問題数
  const available = ALL_QUESTIONS.filter(q=>{
    const catOk = cat==="すべて" || q.cat===cat;
    const notUsed = !usedIds.includes(q.id);
    return catOk && notUsed;
  });

  const saveUsedIds = useCallback((ids)=>{
    setUsedIds(ids);
    store.saveIds(ids);
  },[]);

  const startSession = useCallback(async()=>{
    let picked = [];

    if(weakMode && weakIds.length > 0){
      // 苦手優先：間違えた問題IDから優先出題
      const weakInAll = ALL_QUESTIONS.filter(q => weakIds.includes(q.id));
      const others = ALL_QUESTIONS.filter(q => !weakIds.includes(q.id) && (cat==="すべて" || q.cat===cat));
      const shuffledWeak = shuffle(weakInAll).slice(0, Math.min(10, weakInAll.length));
      const rest = shuffle(others).slice(0, Math.max(0, 10 - shuffledWeak.length));
      picked = shuffle([...shuffledWeak, ...rest]).slice(0, 10);
    } else {
      const base = ALL_QUESTIONS.filter(q=>(cat==="すべて"||q.cat===cat) && !usedIds.includes(q.id));
      if(base.length < 10){
        const fresh = ALL_QUESTIONS.filter(q=>cat==="すべて"||q.cat===cat);
        picked = shuffle(fresh).slice(0,10);
        saveUsedIds(picked.map(q=>q.id));
        // 全問題を1周し終えて新しい周回に入るため、今回の周回成績もリセットする
        setAllHistory([]); setCatStats({}); store.clearCycle();
      } else {
        picked = shuffle(base).slice(0,10);
        saveUsedIds([...usedIds, ...picked.map(q=>q.id)]);
      }
    }

    setQuestions(picked);
    setAnswers(new Array(10).fill(null));
    setQIdx(0); setChosen(null); setShowFb(false);
    setAnalysis(""); setCopyText(""); setCopied(false);
    setPhase("question");
  },[cat, usedIds, weakMode, weakIds, saveUsedIds]);

  const handleAnswer = useCallback((choice)=>{
    if(showFb) return;
    setChosen(choice); setShowFb(true);
    const q = questions[qIdx];
    const ok = choice.label===q.correct;
    setAllHistory(h=>{
      const updatedHistory=[...h,{cat:q.cat,topic:q.topic,correct:ok}];
      setCatStats(prev=>{
        const cur=prev[q.cat]||{ok:0,total:0};
        const updatedStats={...prev,[q.cat]:{ok:cur.ok+(ok?1:0),total:cur.total+1}};
        store.saveCycle({history:updatedHistory, catStats:updatedStats});
        return updatedStats;
      });
      return updatedHistory;
    });
    if(!ok){
      setMissedList(m=>{
        const updated=[...m,q];
        store.saveMissed(updated);
        return updated;
      });
    }
    setAnswers(prev=>{const n=[...prev];n[qIdx]=choice.label;return n;});
  },[showFb,questions,qIdx]);

  const handleNext = useCallback(()=>{
    const next=qIdx+1;
    if(next>=questions.length) setPhase("score");
    else{setQIdx(next);setChosen(null);setShowFb(false);}
  },[qIdx,questions.length]);

  const sessionCorrect = answers.filter((a,i)=>a!==null&&questions[i]&&a===questions[i].correct).length;


  useEffect(()=>{
    if(phase==="score"&&questions.length>0){
      if(copyText===""){
        const now=new Date();
        const ds=`${now.getFullYear()}/${now.getMonth()+1}/${now.getDate()} ${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}`;
        const correct=answers.filter((a,i)=>a!==null&&questions[i]&&a===questions[i].correct).length;
        const lines=[
          `📊 FE科目A クイズ結果 ${ds}`,
          `正解: ${correct}/${questions.length}問 (${Math.round(correct/questions.length*100)}%)`,
          `分野: ${[...new Set(questions.map(q=>q.cat))].join("・")}`,
          `---`,
          ...questions.map((q,i)=>`Q${i+1}[${q.cat}/${q.topic}] ${answers[i]===q.correct?"○":"✗"}`),
          `---`,
          `累計分野別:`,
          ...Object.entries(catStats).map(([c,s])=>`${c}: ${Math.round(s.ok/s.total*100)}% (${s.ok}/${s.total})`),
        ];
        setCopyText(lines.join("\n"));

        // このセッションの分野別集計を作りlocalStorageへ永続化する
        const sessionCats = {};
        questions.forEach((q,i)=>{
          if(!sessionCats[q.cat]) sessionCats[q.cat]={ok:0,total:0};
          sessionCats[q.cat].total+=1;
          if(answers[i]!==null && answers[i]===q.correct) sessionCats[q.cat].ok+=1;
        });
        const session={
          date: now.getTime(),
          cat: cat,
          total: questions.length,
          correct: correct,
          pct: Math.round(correct/questions.length*100),
          cats: sessionCats,
        };
        store.addSession(session);
        setSavedSessions(prev=>{
          const updated=[...prev, session];
          return updated.length>100 ? updated.slice(updated.length-100) : updated;
        });
        setLifetime(store.loadLifetime());
      }
    }
  },[phase]); // eslint-disable-line

  const loadDbHistory = useCallback(()=>{ /* localStorage版は履歴タブで直接表示 */ },[]);

  const clearDbMissed = useCallback(async()=>{
    if(!window.confirm("復習リストを全削除しますか？")) return;
    setDbMissed([]);
  },[]);

  const handleAnalyze = useCallback(async()=>{
    setPhase("analyzing");
    try{
      const result=await analyzeResults(questions,answers,catStats);
      setAnalysis(result);
      setCopyText(prev=>prev+"\n---\n📝 AI分析:\n"+result);
    }catch{setAnalysis("分析の取得に失敗しました。");}
    finally{setPhase("score");}
  },[questions,answers,catStats]);

  const resetSession = useCallback(()=>{setPhase("idle");setAnalysis("");setCopyText("");setCopied(false);},[]);
  const clearMissed = useCallback(()=>{ setMissedList([]); store.saveMissed([]); },[]);

  const totalAnswered=allHistory.length;
  const totalCorrect=allHistory.filter(h=>h.correct).length;
  const overallPct=totalAnswered>0?Math.round(totalCorrect/totalAnswered*100):0;

  return(
    <div style={s.app}>
      <style>{`@keyframes spin{to{transform:rotate(360deg)}} @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&display=swap');`}</style>
      <div style={s.container}>
        <header style={s.header}>
          <div style={s.h1}>FE 科目A Quiz</div>
          <div style={s.sub}>基本情報技術者 — 108問内蔵</div>
          <a href="/b" style={{display:"inline-block",marginTop:8,fontSize:12,color:C.accent,textDecoration:"none",border:`1px solid ${C.accent}`,borderRadius:6,padding:"4px 10px"}}>科目Bの問題を解く →</a>
        </header>

        <div style={s.tabs}>
          {["quiz","review","history"].map((t,i)=>(
            <button key={t} style={s.tabBtn(tab===t)} onClick={()=>{ setTab(t); if(t==="history") loadDbHistory(); }}>
              {["クイズ",`復習${missedList.length>0?` (${missedList.length})`:""}`, "履歴・分析"][i]}
            </button>
          ))}
        </div>

        {tab==="quiz" && <>
          {phase==="idle" && (
            <div style={s.card}>
              {progressLoading ? (
                <div style={{textAlign:"center",padding:20,color:C.muted,fontSize:13}}>
                  <span style={s.spinner}/> <span style={{marginLeft:8}}>進捗を読み込み中…</span>
                </div>
              ) : (
                <div style={{marginBottom:12,fontSize:13,color:C.muted}}>
                  残り問題: <span style={s.stockBadge(available.length)}>{available.length}問</span>
                  <span style={{fontSize:11,color:C.muted,marginLeft:8}}>/ {ALL_QUESTIONS.length}問中</span>
                  {progressError && <div style={{fontSize:11,color:progressError.startsWith("✓")?C.green:C.warn,marginTop:4}}>{progressError}</div>}
                </div>
              )}
              <div style={{marginBottom:16}}>
                <div style={{fontSize:11,color:C.muted,fontFamily:"monospace",marginBottom:8,textTransform:"uppercase",letterSpacing:".06em"}}>分野</div>
                <div style={s.row}>
                  {CATS.map(c=><button key={c} style={s.chip(cat===c)} onClick={()=>setCat(c)}>{c}</button>)}
                </div>
              </div>
              <button style={{...s.btn(),width:"100%"}} onClick={startSession}>
                {weakMode ? "🎯 苦手優先モードでスタート" : "スタート（10問）"}
              </button>
              {/* 苦手優先モード切替 */}
              <div style={{display:"flex",alignItems:"center",gap:10,marginTop:10,padding:"10px 12px",background:weakMode?"rgba(63,185,80,.08)":"rgba(255,255,255,.03)",border:`1px solid ${weakMode?C.green:C.border}`,borderRadius:8,cursor:"pointer"}}
                onClick={async()=>{
                  const next = !weakMode;
                  setWeakMode(next);
                  if(next){
                    // localStorageの復習リストから苦手IDを取得
                    const ids = missedList.map(q=>q.id);
                    setWeakIds([...new Set(ids)]);
                  }
                }}>
                <div style={{width:36,height:20,background:weakMode?C.green:C.border,borderRadius:10,position:"relative",flexShrink:0,transition:"background .2s"}}>
                  <div style={{width:16,height:16,background:"white",borderRadius:"50%",position:"absolute",top:2,left:weakMode?18:2,transition:"left .2s"}}/>
                </div>
                <div>
                  <div style={{fontSize:13,color:weakMode?C.green:C.muted,fontWeight:weakMode?700:400}}>苦手優先モード</div>
                  <div style={{fontSize:11,color:C.muted}}>{weakMode && weakIds.length>0 ? `${weakIds.length}問を優先出題` : "復習リストの問題を優先"}</div>
                </div>
              </div>
              <button style={{width:"100%",padding:9,background:"none",border:`1px solid ${C.border}`,color:C.muted,borderRadius:8,fontFamily:"inherit",fontSize:12,cursor:"pointer",marginTop:8}}
                onClick={()=>{ if(window.confirm("使用済み問題をリセットして全問を出題可能にします。今回の周回成績もリセットされます。よろしいですか？")){ saveUsedIds([]); setAllHistory([]); setCatStats({}); store.clearCycle(); } }}>
                🔄 問題をリセット（全108問に戻す）
              </button>
            </div>
          )}

          {phase==="question" && questions[qIdx] && (()=>{
            const q=questions[qIdx];
            return(
              <div>
                <div style={s.progress}><div style={s.bar((qIdx/questions.length)*100)}/></div>
                <div style={s.card}>
                  <div style={s.meta}>
                    <span style={{fontFamily:"monospace",fontSize:12,color:C.muted}}>{qIdx+1} / {questions.length}</span>
                    <span style={s.catTag}>{q.cat}</span>
                  </div>
                  <div style={s.qnum}>テーマ: {q.topic}</div>
                  <div style={s.qtext}>{q.q}</div>
                  <div>
                    {q.choices.map(c=>{
                      let state=null;
                      if(showFb){if(c.label===q.correct)state="correct";else if(chosen?.label===c.label)state="wrong";}
                      return(
                        <button key={c.label} style={s.choiceBtn(state)} onClick={()=>handleAnswer(c)} disabled={showFb}>
                          <span style={s.label}>{c.label}</span><span>{c.text}</span>
                        </button>
                      );
                    })}
                  </div>
                  {showFb && (
                    <div>
                      <div style={s.fb(chosen?.label===q.correct)}>
                        {chosen?.label===q.correct?"✓ 正解！":`✗ 不正解。正解は ${q.correct}. ${q.choices.find(c=>c.label===q.correct)?.text}`}
                        <div style={s.hintBox}><div style={s.hintLabel}>解説</div>{q.hint}</div>
                        {chosen?.label!==q.correct && (
                          <div style={{...s.hintBox,marginTop:8,borderColor:"rgba(248,81,73,.2)"}}>
                            <div style={{...s.hintLabel,color:C.warn}}>あなたの選択</div>
                            {chosen?.label}. {chosen?.text}
                          </div>
                        )}
                      </div>
                      <button style={{...s.btn(),width:"100%",marginTop:14}} onClick={handleNext}>
                        {qIdx+1>=questions.length?"結果を見る":"次の問題 →"}
                      </button>
                    </div>
                  )}
                </div>
              </div>
            );
          })()}

          {(phase==="score"||phase==="analyzing") && (
            <div style={{...s.card,textAlign:"center"}}>
              <div style={{fontFamily:"monospace",fontSize:48,fontWeight:600,color:C.accent,marginBottom:4}}>
                {sessionCorrect} / {questions.length}
              </div>
              <div style={{color:C.muted,fontSize:13,marginBottom:20}}>
                正解率 {Math.round(sessionCorrect/questions.length*100)}%
                {Math.round(sessionCorrect/questions.length*100)>=80?" — 完璧に近い！":Math.round(sessionCorrect/questions.length*100)>=60?" — 惜しい、復習しよう":" — 復習タブで確認を"}
              </div>
              <div style={{textAlign:"left",marginBottom:20}}>
                {questions.map((q,i)=>{
                  const ok=answers[i]===q.correct;
                  return(
                    <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",padding:"7px 0",borderBottom:`1px solid ${C.border}`,gap:8}}>
                      <div style={{fontSize:12}}>
                        <span style={{fontFamily:"monospace",color:C.muted,marginRight:6}}>Q{i+1}</span>
                        <span style={{color:C.muted,fontSize:11}}>[{q.cat}]</span>
                        <span style={{marginLeft:6}}>{q.topic}</span>
                      </div>
                      <span style={{fontFamily:"monospace",color:ok?C.green:C.red,flexShrink:0}}>{ok?"○":"✗"}</span>
                    </div>
                  );
                })}
              </div>
              <div style={{display:"flex",gap:8,justifyContent:"center",flexWrap:"wrap",marginBottom:16}}>
                <button style={s.btn()} onClick={startSession}>もう一度</button>
                <button style={s.btn(C.accent,true)} onClick={resetSession}>設定に戻る</button>
              </div>
              <div style={{textAlign:"left"}}>
                <div style={s.sectionTitle}>AI 学習分析</div>
                {analysis?(
                  <div style={s.analysisBox}>{analysis}</div>
                ):(
                  <button style={{...s.btn(C.green),width:"100%"}} onClick={handleAnalyze} disabled={phase==="analyzing"}>
                    {phase==="analyzing"?<><span style={s.spinner}/><span style={{marginLeft:8}}>分析中…</span></>:"このセッションをAIに分析してもらう"}
                  </button>
                )}
              </div>
              {copyText && (
                <div style={{textAlign:"left",marginTop:20}}>
                  <div style={s.sectionTitle}>📋 チャットに貼り付ける用</div>
                  <div style={{display:"flex",justifyContent:"flex-end",marginBottom:4}}>
                    <button style={s.copyBtn(copied)} onClick={()=>{
                      navigator.clipboard.writeText(copyText).then(()=>{setCopied(true);setTimeout(()=>setCopied(false),2000);})
                      .catch(()=>{const el=document.getElementById("copyarea");if(el){el.select();document.execCommand("copy");setCopied(true);setTimeout(()=>setCopied(false),2000);}});
                    }}>{copied?"✓ コピーしました":"コピー"}</button>
                  </div>
                  <textarea id="copyarea" readOnly value={copyText}
                    style={{...s.copyBox,width:"100%",resize:"none",outline:"none"}} rows={8}/>
                  <div style={{fontSize:11,color:C.muted,marginTop:4}}>コピーしてチャットに貼り付けると履歴として残ります</div>
                </div>
              )}
            </div>
          )}
        </>}

        {tab==="review" && (
          <div>
            {missedList.length===0
              ?<div style={{textAlign:"center",color:C.muted,fontSize:14,padding:"48px 0"}}>間違えた問題はまだありません。</div>
              :<>
                {/* コピーテキスト生成 */}
                <ReviewCopyBox missedList={missedList} lifetimeByCat={lifetime.byCat||{}}/>
                <button style={{width:"100%",padding:9,background:"none",border:`1px solid ${C.border}`,color:C.muted,borderRadius:8,fontFamily:"inherit",fontSize:13,cursor:"pointer",marginBottom:16}} onClick={clearMissed}>復習リストをクリア</button>
                {missedList.map((q,i)=>{
                  const cc=q.choices.find(c=>c.label===q.correct);
                  return(
                    <div key={i} style={s.reviewItem}>
                      <div style={{fontSize:11,color:C.muted,fontFamily:"monospace",marginBottom:4}}>{q.cat} / {q.topic}</div>
                      <div style={{fontSize:13,fontWeight:500,lineHeight:1.6,marginBottom:8}}>{q.q}</div>
                      <div style={s.hintLabel}>正解</div>
                      <div style={{fontSize:13,color:C.text,marginBottom:6,lineHeight:1.5}}>{q.correct}. {cc?.text}</div>
                      <div style={{fontSize:12,color:C.muted,lineHeight:1.6}}>{q.hint}</div>
                    </div>
                  );
                })}
              </>
            }
          </div>
        )}

        {tab==="history" && (
          <div>
            <div style={{display:"flex",gap:8,marginBottom:18}}>
              {[["解答数",totalAnswered],["正解数",totalCorrect],["正解率",`${overallPct}%`]].map(([l,v],i)=>(
                <div key={l} style={s.statBox}>
                  <div style={{...s.statNum,color:i===2?rateColor(overallPct):C.accent}}>{v}</div>
                  <div style={s.statLabel}>{l}（今の周回）</div>
                </div>
              ))}
            </div>
            {Object.keys(catStats).length>0 && <>
              <div style={s.sectionTitle}>分野別 正解率（今の周回・{ALL_QUESTIONS.length}問を1周する間ずっと蓄積）</div>
              {Object.entries(catStats)
                .map(([c,st])=>({c,pct:Math.round(st.ok/st.total*100),ok:st.ok,total:st.total}))
                .sort((a,b)=>a.pct-b.pct)
                .map(({c,pct,ok,total})=>(
                  <div key={c} style={s.catBarRow}>
                    <div style={{fontSize:12,width:140,flexShrink:0,lineHeight:1.3}}>{c}</div>
                    <div style={{flex:1,height:7,background:C.surface2,borderRadius:4,overflow:"hidden"}}>
                      <div style={{height:"100%",borderRadius:4,width:`${pct}%`,background:rateColor(pct),transition:"width .4s"}}/>
                    </div>
                    <div style={{fontFamily:"monospace",fontSize:12,width:72,textAlign:"right",color:rateColor(pct)}}>
                      {pct}% ({ok}/{total})
                    </div>
                  </div>
                ))
              }
            </>}

            {/* 累計成績(fe_lifetime基準、間引かれない真の累計)＋直近セッション一覧(表示専用) */}
            {(lifetime.totalAnswered > 0 || savedSessions.length > 0) && (()=>{
              const totalA = lifetime.totalAnswered;
              const totalC = lifetime.totalCorrect;
              const ovPct = totalA>0?Math.round(totalC/totalA*100):0;
              const aggCats = lifetime.byCat || {};
              return <>
                <div style={s.sectionTitle}>📦 累計（全セッション）</div>
                <div style={{display:"flex",gap:8,marginBottom:12}}>
                  {[["累計解答",totalA],["累計正解",totalC],["累計正解率",`${ovPct}%`]].map(([l,v],i)=>(
                    <div key={l} style={s.statBox}>
                      <div style={{...s.statNum,color:i===2?rateColor(ovPct):C.accent,fontSize:16}}>{v}</div>
                      <div style={s.statLabel}>{l}</div>
                    </div>
                  ))}
                </div>
                {Object.keys(aggCats).length>0 && <>
                  <div style={s.sectionTitle}>累計分野別正解率</div>
                  {Object.entries(aggCats)
                    .map(([c,st])=>({c,pct:Math.round(st.ok/st.total*100),ok:st.ok,total:st.total}))
                    .sort((a,b)=>a.pct-b.pct)
                    .map(({c,pct,ok,total})=>(
                      <div key={c} style={s.catBarRow}>
                        <div style={{fontSize:12,width:140,flexShrink:0,lineHeight:1.3}}>{c}</div>
                        <div style={{flex:1,height:7,background:C.surface2,borderRadius:4,overflow:"hidden"}}>
                          <div style={{height:"100%",borderRadius:4,width:`${pct}%`,background:rateColor(pct),transition:"width .4s"}}/>
                        </div>
                        <div style={{fontFamily:"monospace",fontSize:12,width:72,textAlign:"right",color:rateColor(pct)}}>{pct}% ({ok}/{total})</div>
                      </div>
                    ))
                  }
                </>}
                <div style={s.sectionTitle}>直近のセッション（最新20件）</div>
                <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"4px 13px",marginBottom:12}}>
                  {savedSessions.slice(-20).reverse().map((sess,i)=>{
                    const d=new Date(sess.date);
                    const ds=`${d.getMonth()+1}/${d.getDate()} ${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`;
                    return(
                      <div key={i} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 0",borderBottom:i<Math.min(savedSessions.length,20)-1?`1px solid ${C.border}`:"none"}}>
                        <span style={{fontSize:12,color:C.muted,fontFamily:"monospace"}}>{ds} ・ {sess.cat}</span>
                        <span style={{fontFamily:"monospace",fontSize:13,fontWeight:600,color:rateColor(sess.pct)}}>{sess.correct}/{sess.total}</span>
                      </div>
                    );
                  })}
                </div>
                <button style={{width:"100%",padding:9,background:"none",border:`1px solid ${C.border}`,color:C.muted,borderRadius:8,fontFamily:"inherit",fontSize:12,cursor:"pointer"}}
                  onClick={()=>{ if(window.confirm("直近のセッション一覧のみ削除します(累計成績は消えません)。よろしいですか？")){ localStorage.removeItem("fe_sessions"); setSavedSessions([]); } }}>
                  直近セッション一覧をクリア
                </button>
              </>;
            })()}
            {totalAnswered===0 && savedSessions.length===0 && <div style={{textAlign:"center",color:C.muted,fontSize:13,padding:"12px 0"}}>クイズに挑戦すると履歴が表示されます。</div>}
          </div>
        )}
      </div>
    </div>
  );
}
